// Busca en la ejecución que falló qué se estaba procesando y decide qué hacer: en los 03 marcar el documento, en los 01 sacar el correo de la carpeta
const aviso = $('Error Trigger').first().json;
const ejecucion = $input.first().json;
const runData = (ejecucion && ejecucion.data && ejecucion.data.resultData && ejecucion.data.resultData.runData) || {};
const salida = nodo => runData[nodo]?.[0]?.data?.main?.[0]?.[0]?.json;
const corrio = nodos => nodos.some(n => Boolean(runData[n]));
const leida = Boolean(ejecucion && ejecucion.data);
const flujoId = aviso.workflow?.id;

// 03 - Envía ERM (Liquidación, Factura o Pedido): los tres flujos usan casi los mismos nombres de nodo
const esLiquidaciones = flujoId === 'CfNMFXcjUOEGDpWo';
const esFacturasEnvio = flujoId === 'Qsc1oQE0bgz5ttj2';
const esPedidosEnvio = flujoId === 'cP9Zly2bnD1pUcUK';
const esEnvio = esLiquidaciones || esFacturasEnvio || esPedidosEnvio;
const cabecera = (esEnvio && (salida('Recuperamos fecha y hora') || salida('Leer cabezera'))) || {};
const idProceso = esEnvio
  ? (cabecera.id_proceso || salida('Update Estado')?.id_proceso || salida('Updateamos Estado')?.id_proceso || salida('Tomamos solo una')?.id_proceso || salida('Buscamos actualización')?.id_proceso || '')
  : '';
const estadoFinal = corrio(['Update enviada', 'Update procesado', 'Update error']);
const yaLlamadoT2000 = Boolean(runData['Enviamos API T2000']) && !estadoFinal;
const marcar = Boolean(idProceso) && !yaLlamadoT2000 && !estadoFinal;
const documento = esPedidosEnvio ? 'el pedido' : esFacturasEnvio ? 'la factura' : 'la liquidación';
const bloqueo = esPedidosEnvio ? 'A Pedido' : esFacturasEnvio ? 'A Facturas' : 'A Liquidación';

// 01 - Extrae de Outlook (Liquidaciones y Facturas en el buzón de Facturas; Pedidos en el suyo)
const esPedidosCorreo = flujoId === '3aU2QaO5TUhIH391';
const esExtraccion = ['zO613EETvS4k2W0O', 'RlO14JqBGbrGrPJw'].includes(flujoId) || esPedidosCorreo;
const correo = (esExtraccion && (salida('Generar ID Datos') || salida('Filtramos firmas') || salida('Get many folder messages'))) || {};
const mensajeId = correo.message_id || correo.id || '';
const correoMovido = corrio(['Facturas procesadas', 'Facturas Error', 'PEdidos procesados', 'Gastos procesados', 'PEdidos Error']);
const registrada = corrio(['Actualizamos En proceso', 'Inserta registro Gasto']);
const mover = esExtraccion && Boolean(mensajeId) && !correoMovido;

const error = aviso.execution?.error || aviso.trigger?.error || {};
const nodo = aviso.execution?.lastNodeExecuted || '';
const mensaje = error.message || 'Error sin mensaje';

let estadoHoja = 'Sin cambios.';
if (marcar) estadoHoja = esPedidosEnvio ? 'Marcado como Rechazado. Para reintentar, vuelve a ponerlo en OK.' : 'Marcada como Rechazada. Para reintentar, vuelve a ponerla en OK.';
else if (yaLlamadoT2000) estadoHoja = 'Sin cambios (sigue en "' + bloqueo + '"): ya se había llamado a T2000. Comprueba en T2000 si llegó antes de volver a ponerlo en OK.';
else if (estadoFinal) estadoHoja = 'Sin cambios: la fila ya tenía su estado final.';
else if (mover && registrada) estadoHoja = 'Correo movido a la carpeta Errores. Ya se había registrado en la hoja' + (correo.id_proceso ? ' (' + correo.id_proceso + ')' : '') + ', así que eso seguirá su curso; si el correo traía varios documentos, comprueba que estén todos antes de reintentar.';
else if (mover) estadoHoja = 'Correo movido a la carpeta Errores sin registrar nada. Para reintentar, vuelve a moverlo a la carpeta de la que salió.';
else if (esExtraccion && correoMovido) estadoHoja = 'Sin cambios: el correo ya se había movido de la carpeta.';
else if (esExtraccion) estadoHoja = 'No se ha llegado a leer ningún correo' + (leida ? '.' : ' (no se pudo leer la ejecución).');
else if (esEnvio) estadoHoja = 'No se ha podido identificar ' + documento + (leida ? '.' : ' (no se pudo leer la ejecución).');

const numero = cabecera.numero_factura || cabecera.numero_pedido;

return [{
  json: {
    flujo: aviso.workflow?.name || '',
    nodo,
    mensaje,
    enlace: aviso.execution?.url || '',
    id_proceso: idProceso,
    numero_factura: numero ? String(numero) : '',
    emisor_nombre: cabecera.emisor_nombre || cabecera.cliente_nombre || '',
    correo_asunto: correo.asunto_email || correo.subject || '',
    mensaje_id: mensajeId,
    marcar_rechazada: marcar,
    hoja: esPedidosEnvio ? 'pedidos' : esFacturasEnvio ? 'facturas' : 'liquidaciones',
    mover_a_errores: mover,
    buzon: esPedidosCorreo ? 'pedidos' : 'facturas',
    estado_hoja: estadoHoja,
    motivo: ('Error en n8n (' + nodo + '): ' + mensaje).slice(0, 500)
  }
}];

